#!/usr/bin/env node

/*
 * Log speech audio samples to S3 via the logAsrBinary server API.
 * 
 */

"use strict";

const parseArgs = require("minimist");

const identity_file = "/var/jibo/identity.json";
const credentials_file = "/var/jibo/credentials.json";

let args = process.argv.slice(2);
let argv = parseArgs(args);

function usage() {
  console.log("Usage:", process.argv[1], "[options] file0.pcm [file1.pcm [file2.pcm [...]]]");
  console.log("");
  console.log("OPTIONS:");
  console.log("  -h,--help            print this message");
  console.log("  -k,--keep            keep files, don't delete them after uploading (handy for testing)");
  console.log(`  --credentials FILE   path to credentials.json (default: ${credentials_file})`);
}

if (argv.h || argv.help) {
  usage();
  process.exit(0);
}

if (argv._.length == 0) {
  process.exit(0);
}

/*
 * Do the requires only after determining that there's work to do.
 */ 

const fs = require("fs");
const Jibo = require("@jibo/jibo-server-client");
const syslog = require("modern-syslog");
const url = require('url');
const async = require('async');

argv.credentials = argv.credentials || credentials_file;
argv.keep = argv.k || argv.keep;

function get_identity() {
  try {
    let id = JSON.parse(fs.readFileSync(identity_file));
    return id;
  } catch (error) {
    syslog.error("Failed to read identity:", error);
    process.exit(1);
  }
}

if (!fs.existsSync(argv.credentials)) {
  let err = `ERROR: Credentials file "${argv.credentials}" not found.`;
  syslog.warn(err);
  console.log(err);
  process.exit(1);
}


Jibo.config.loadFromPath(argv.credentials);

//TODO: uncomment on the robot
let identity = get_identity();


syslog.init("jibo-log-asr", syslog.LOG_PID | syslog.LOG_ODELAY, syslog.LOG_LOCAL0);

function upload_file(fileName, callback) {
  const filesize = fs.statSync(fileName).size;
  syslog.info("Upload audio", fileName, " size", filesize, "bytes");

  let parts = fileName.split(".");
  // Filenames are of the form:
  // 2018-04-30T17.26.26.703Z.enroll.5ae204fb7850750010426749.gid-226c452e-4cbd-11e8-aeac-8cae4cf576b1.1.GOOD.pcm
  let trackingId = parts[4];
  new Jibo.Log().putAsrBinary({
    trackingId,
    metadata: {
      robot_serial_number: identity.serial_number,
      robot_name: identity.name,
      original_file_name: fileName.replace(/.*\//, '')
    }
  }, (err, result) => {
    if (err) {
      console.error(err);
      return callback(err);
    }

    const https = require('https');
    const uploadUrl = url.parse(result.uploadUrl);
    const options = {
      method: 'PUT',
      host: uploadUrl.host,
      path: uploadUrl.path,
      headers: {
        Accept: '*/*',
        'Content-Type': 'application/octet-stream',
        'Content-Length': filesize //Content-Length is required to upload to AWS S3 pre-signed URL
      }
    }
    let readStream = fs.createReadStream(fileName);
    let request = https.request(options, res => uploadCb(res, callback));
    request.on('error', e => {
      console.error(`problem with request: ${e.message}`);
      callback(e);
    });
    readStream.on('data', chunk => request.write(chunk));
    readStream.on('end', () => {
      request.end();
    });
  });
}

function uploadCb(res, callback) {
  let responseBody = '';
  res.on('data', (chunk) => {
    responseBody += chunk;
  });
  res.on('end', () => {
    if (res.statusCode >= 300) {
      console.log(`STATUS: ${res.statusCode}, HEADERS: ${JSON.stringify(res.headers)}, BODY:${responseBody}`);
    }
    callback();
  });
}

async.eachSeries(argv._, (filename, callback) => {
  upload_file(filename, (e) => {
    if (!e) {
      if (!argv.keep) {
        fs.unlinkSync(filename);
      }  
    }
    callback(e);
  })
}, (err) => {
  if (err) {
    console.log(`Uploading ended with an error: ${err}`);
  } else {
    // console.log('Upload completed.');
  }
});

